(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.03-t*0.4)*8 + Math.cos((y+wy1)*0.025+t*0.3)*6;
  const wy2 = Math.cos((y+wy1)*0.03+t*0.35)*8 + Math.sin((x+wx1)*0.028-t*0.45)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*40,0.095,1.8]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d*f*2.5-t*sp*1.3)*0.4; iS2+=Math.sin(d*f*1.8+t*sp*0.9+2.0)*0.4;
  }
  const n=src.length, act=aS/n+aS2/n, inh=iS/n+iS2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.035-t*0.6))/3
    +Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15
    +Math.sin(sx*0.08*Math.cos(t*0.2)+sy*0.06*Math.sin(t*0.15)+t*0.5)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*5+t*0.8)*0.5)/2.5*0.4;
  const cSeed=[[100,50],[200,80],[350,150],[60,180],[400,60],[250,200],[150,130],[300,30]];
  let mC=999,mC2=999;
  for(const[vx,vy]of cSeed){
    const cd=Math.sqrt((sx-vx-Math.sin(t*0.4+vx*0.1)*20)**2+(sy-vy-Math.cos(t*0.35+vy*0.1)*20)**2);
    if(cd<mC){mC2=mC;mC=cd}else if(cd<mC2)mC2=cd;
  }
  const cell=(1-Math.min(1,(mC2-mC)*0.15))*0.4;
  const feed=act-inh*0.7+bg*0.3+spiral-cell*0.5;
  const r1=Math.tanh(feed*2.2), r2=Math.tanh((feed*0.8+r1*0.5)*1.8);
  const fR=r1*0.6+r2*0.4;
  const moire=Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx+sy)*0.15+t)*0.5;
  const v=(fR*0.7+Math.tanh(moire*1.5)*0.3)*0.5+0.5;
  const pal=[[5,12,45],[12,40,80],[20,75,110],[30,120,130],[60,165,140],[140,200,130],[210,200,90],[230,150,80],[200,100,70],[160,60,80],[100,30,70],[50,18,55],[5,12,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(fR*Math.PI)*0.25;
  const edge=Math.abs(fR)>0.6?1.2:Math.abs(fR)>0.3?1.05:0.95;
  const glow=Math.max(0,fR*0.5)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*255)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*200)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*150)|0)
  ];
}
